#!/usr/bin/env python3
"""Build crawlable collections from the same catalog as the interactive homepage."""
from pathlib import Path
import json, html
from urllib.parse import urlparse
R=Path(__file__).resolve().parents[1]; ORIGIN='https://www.drunkyetistudio.com'; esc=html.escape
CATEGORIES=[('games','Games','Indie games','Explore Drunk Yeti’s indie games, from arcade experiments to card games and unusual adventures. Open a release page for its latest builds, supported devices and play options.'),('tools','Tools','Game makers & creative tools','Find Drunk Yeti software for creating games, art, music and more. Each release page explains the current features, downloads and license.'),('assets','Assets','Game asset packs','Browse Drunk Yeti asset packs for your next project. Check each pack’s store page for included files, formats and licensing terms.'),('mods','Mods','Game mods','Explore Drunk Yeti mods and new ways to play. Read the release page for compatible game versions, requirements and installation instructions.'),('soundtracks','Soundtracks','Game soundtracks','Listen beyond the game with Drunk Yeti soundtrack releases. Follow a release to its official store for tracks, previews and purchase options.'),('os','OS','Linux operating systems','Explore PlaySpace and Prismatic, Drunk Yeti’s Linux projects for gaming and creative work. Review the project pages for current requirements and installation guidance.'),('comics','Comics','Comics & illustrated stories','Discover illustrated stories and comics from Drunk Yeti. Visit each publication’s release page for previews and available editions.')]
nav=''.join(f'<a href="/{slug}/">{esc(title)}</a>' for slug,_,title,_ in CATEGORIES)
def page(path,title,description,body,schema=None):
    url=ORIGIN+path
    metadata={'@context':'https://schema.org','@type':'WebPage','name':title,'description':description,'url':url} if schema is None else schema
    data=json.dumps(metadata,ensure_ascii=False).replace('<','\\u003c')
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} | Drunk Yeti Studio</title><meta name="description" content="{esc(description,quote=True)}"><link rel="canonical" href="{url}"><meta name="robots" content="index,follow,max-image-preview:large"><meta property="og:type" content="website"><meta property="og:site_name" content="Drunk Yeti Studio"><meta property="og:title" content="{esc(title,quote=True)}"><meta property="og:description" content="{esc(description,quote=True)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{ORIGIN}/assets/social-preview-v1.png"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/favicon.ico"><link rel="stylesheet" href="/collections.css"><script type="application/ld+json">{data}</script></head><body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="/">DRUNK YETI <small>STUDIO</small></a><a href="/account/">Your account ↗</a></header><nav aria-label="Collections">{nav}</nav><main id="main"><p class="eyebrow">INDEPENDENT GAMES · CREATIVE SOFTWARE · ORIGINAL WORLDS</p><h1>{esc(title)}</h1><p class="intro">{esc(description)}</p>{body}</main><footer><a href="/about/">About the studio</a><a href="/help/">Help & support</a><a href="/privacy/">Privacy</a><a href="/delete-account/">Account deletion</a><p>Drunk Yeti Studio · by 3ichael 7ambert</p></footer></body></html>'''
def write(path,data):
    p=R/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(data)
def main():
    cards=json.loads((R/'assets/catalog.json').read_text());urls=['/','/about/','/help/','/privacy/']
    for slug,category,title,description in CATEGORIES:
        items=[c for c in cards if c['category']==category]; markup=[]
        for c in items:
            assert urlparse(c['url']).scheme=='https' and urlparse(c['url']).hostname in ('drunkyeti.itch.io','store.steampowered.com')
            img='/'+c['image'].removeprefix('./') if c['image'].startswith('./') else c['image']
            markup.append(f'<article><a href="{esc(c["url"],quote=True)}"><img src="{esc(img,quote=True)}" alt="{esc(c["title"],quote=True)} cover" loading="lazy" width="315" height="250"><h2>{esc(c["title"])}</h2></a><p>{esc(c.get("description") or "See the official release page for details and downloads.")}</p><a class="release" href="{esc(c["url"],quote=True)}">View release ↗</a></article>')
        body='<p class="note">Availability, prices and platform support are listed on each official release page.</p><div class="grid">'+''.join(markup)+'</div>'
        schema={'@context':'https://schema.org','@type':'CollectionPage','name':title,'description':description,'url':ORIGIN+'/'+slug+'/','mainEntity':{'@type':'ItemList','numberOfItems':len(items),'itemListElement':[{'@type':'ListItem','position':i+1,'name':c['title'],'url':c['url']} for i,c in enumerate(items)]}}
        write(slug+'/index.html',page('/'+slug+'/',title,description,body,schema));urls.append('/'+slug+'/')
    write('about/index.html',page('/about/','About Drunk Yeti Studio','Independent games, creative software and original worlds from Drunk Yeti Studio.', '<section><h2>Design with a technical mind.</h2><p>Drunk Yeti brings games, creative software and original characters together. The studio explores arcade play, tools for making games, music and art, and a growing collection of original worlds.</p><p>Michael Lambert Jr creates under the signature <strong>3ichael 7ambert</strong>. Explore the current releases and follow the studio for new work.</p><h2>Find the official studio</h2><p><a href="https://drunkyeti.itch.io">itch.io releases</a> · <a href="https://store.steampowered.com/curator/45875400">Steam</a> · <a href="https://www.youtube.com/channel/UCT4krkccy2JVXcyzIQi8ZPw/">YouTube</a></p><h2>Contact</h2><p>For account, game or purchase help, email <a href="mailto:support@drunkyetistudio.com">support@drunkyetistudio.com</a>.</p></section>'))
    write('help/index.html',page('/help/','Account & game support','Get help signing in, connecting social accounts, recovering a password and finding your Drunk Yeti purchases.', '''<section><h2>Sign in or recover your account</h2><p>Open <a href="/account/">Your account</a> and use your original sign-in method. For email accounts, choose Forgot password, enter your email and follow the recovery link. Check spam if the message is missing. Never send us your password or verification code.</p><h2>Connect Apple or another social account</h2><p>Sign in to your existing account first, then open Social accounts and choose Connect beside the provider. This helps keep purchases and progress together. Apple’s Hide My Email can provide a different address; avoid creating a second account for an existing profile.</p><h2>Where are my downloads and purchases?</h2><p>Store purchases and downloads are managed by the store where you bought them. Check that store’s purchase history. Shards and eligible Frostpass benefits appear in your Drunk Yeti account. Supported features vary by game and build; consult the game’s release page.</p><h2>How do I change my username?</h2><p>Open Profile in your account. Usernames use 3–24 lowercase letters, numbers or underscores and start with a letter. Display names can use up to 48 characters.</p><h2>Manage privacy and email</h2><p>You can update newsletter preferences in Profile, <a href="/unsubscribe/">unsubscribe</a>, export game data from Security or <a href="/delete-account/">request account deletion</a>.</p><h2>Still need help?</h2><p>Email <a href="mailto:support@drunkyetistudio.com">support@drunkyetistudio.com</a> with the game, device, app version and a description of the issue. For purchases, include the store and order reference. Do not include passwords, payment-card details or sign-in codes.</p></section>'''))
    write('sitemap.xml','<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+ORIGIN+u+'</loc></url>' for u in urls)+'</urlset>\n')
    write('robots.txt','User-agent: *\nAllow: /\n\nSitemap: '+ORIGIN+'/sitemap.xml\n')
    print(f'Built {len(urls)} sitemap URLs and seven crawlable collections.')
if __name__=='__main__':main()
